package net.civeira.phylax.feature.access.role.application.usecase.create;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServerReference;
import net.civeira.phylax.feature.access.role.domain.RoleChangeSet;

class RoleCreateInputUnitTest {

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the role input values are kept when converted to a change set and back")
  void test_role_create_input_change_set_round_trip() {
    RoleCreateInput input = RoleCreateInput.builder().uid("one").name("one")
        .resourceServer(ResourceServerReference.of("one")).version(1).build();
    RoleChangeSet changes = input.toChangeSet();
    Assertions.assertNotNull(changes, "A change set must be created");
    RoleCreateInput copy = RoleCreateInput.fromChangeSet(changes);
    Assertions.assertTrue(input.getUid().isPresent(), "uid must be assigned by the builder");
    Assertions.assertEquals(input.getUid(), copy.getUid(),
        "uid must survive the change set round trip");
    Assertions.assertTrue(input.getName().isPresent(), "name must be assigned by the builder");
    Assertions.assertEquals(input.getName(), copy.getName(),
        "name must survive the change set round trip");
    Assertions.assertTrue(input.getResourceServer().isPresent(),
        "resourceServer must be assigned by the builder");
    Assertions.assertEquals(input.getResourceServer(), copy.getResourceServer(),
        "resourceServer must survive the change set round trip");
    Assertions.assertTrue(input.getVersion().isPresent(),
        "version must be assigned by the builder");
    Assertions.assertEquals(input.getVersion(), copy.getVersion(),
        "version must survive the change set round trip");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the role input builder can generate a new identifier")
  void test_role_create_input_new_uid() {
    RoleCreateInput input = RoleCreateInput.builder().newUid().build();
    Assertions.assertTrue(input.getUid().isPresent(), "A new uid must be generated");
    Assertions.assertTrue(input.getVersion().isPresent(), "The initial version must be assigned");
    Assertions.assertNotEquals(input.getUid(), RoleCreateInput.builder().newUid().build().getUid(),
        "Each new uid must be different");
  }

  /**
   * @autogenerated CreateInputGenerator
   */
  @Test
  @DisplayName("Test the role input starts empty and the setters assign values")
  void test_role_create_input_setters() {
    RoleCreateInput empty = RoleCreateInput.builder().build();
    Assertions.assertTrue(empty.getUid().isEmpty(), "uid must be empty by default");
    Assertions.assertSame(empty, empty.setUid("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getUid().isPresent(), "uid must be assigned by the setter");
    Assertions.assertTrue(empty.getName().isEmpty(), "name must be empty by default");
    Assertions.assertSame(empty, empty.setName("one"), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getName().isPresent(), "name must be assigned by the setter");
    Assertions.assertTrue(empty.getResourceServer().isEmpty(),
        "resourceServer must be empty by default");
    Assertions.assertSame(empty, empty.setResourceServer(ResourceServerReference.of("one")),
        "The setter must allow a flow code");
    Assertions.assertTrue(empty.getResourceServer().isPresent(),
        "resourceServer must be assigned by the setter");
    Assertions.assertTrue(empty.getVersion().isEmpty(), "version must be empty by default");
    Assertions.assertSame(empty, empty.setVersion(1), "The setter must allow a flow code");
    Assertions.assertTrue(empty.getVersion().isPresent(), "version must be assigned by the setter");
    Assertions.assertNotNull(empty.toChangeSet(), "A change set must be created");
  }
}
